from pathlib import Path
import json,subprocess
x=subprocess.run(['systemctl','show','sponge-pi3b-swapguard-v2.service','-p','ActiveState','-p','MainPID'],capture_output=True,text=True,timeout=10)
service=dict(line.split('=',1) for line in x.stdout.splitlines());assert service==dict(ActiveState='inactive',MainPID='0')
rows=[]
for p in sorted(Path('/sys/block').iterdir()):
 if not p.name.startswith('sd'):continue
 fields={}
 for name in ('dev','removable','size','stat','device/vendor','device/model','device/state'):
  try:fields[name]=(p/name).read_text().strip()
  except OSError as e:fields[name]=dict(unavailable=type(e).__name__)
 usb=[]
 for parent in (p/'device').resolve().parents:
  if (parent/'idVendor').exists() and (parent/'idProduct').exists():
   usb.append({name:(parent/name).read_text().strip() for name in ('idVendor','idProduct','manufacturer','product') if (parent/name).exists()})
 rows.append(dict(name=p.name,resolved_sysfs=str(p.resolve()),fields=fields,usb_ancestors=usb))
mounts=[]
for line in Path('/proc/self/mountinfo').read_text().splitlines():
 fields=line.split();major_minor=fields[2]
 if any(r['fields']['dev']==major_minor for r in rows):mounts.append(dict(device=major_minor,mountpoint=fields[4]))
print(json.dumps(dict(service=service,sd_devices=rows,matching_mounts=mounts,scope='Read-only sysfs block-device metadata, no media contents/mount/eject/change')))
